"""Normalized deployment model and canonical JSON helpers."""

import json

import networkx as nx

__all__ = ["Model", "canonical_json"]


def canonical_json(value) -> str:
    """Return strict canonical JSON for JSON-compatible ``value``."""
    raise NotImplementedError


class Model:
    """Immutable snapshot of services, hosts, and a weighted host network."""

    def __init__(self, services, hosts, network) -> None:
        """Normalize and validate inputs; raise ValueError on invalid input."""
        raise NotImplementedError

    @property
    def services(self) -> dict:
        """Return a defensive normalized copy of the services mapping."""
        raise NotImplementedError

    @property
    def hosts(self) -> dict:
        """Return a defensive normalized copy of the hosts mapping."""
        raise NotImplementedError

    @property
    def network(self) -> nx.Graph:
        """Return a defensive copy of the normalized network (all nodes, weighted edges)."""
        raise NotImplementedError

    @property
    def fingerprint(self) -> str:
        """Return the SHA-256 hex digest of the canonical normalized model."""
        raise NotImplementedError

"""Atomic JSON persistence and append-only revisioned event journal."""

__all__ = ["ConflictError", "Journal", "save_json"]


class ConflictError(Exception):
    """Raised when an append conflicts with the journal state."""


def save_json(path: str, value: object) -> None:
    """Atomically write canonical strict JSON ``value`` to ``path``."""
    raise NotImplementedError


class Journal:
    """Append-only JSON event journal with fcntl-locked optimistic concurrency."""

    def __init__(self, path: str) -> None:
        """Record the journal path; perform no I/O."""
        raise NotImplementedError

    def read(self) -> dict:
        """Return defensive {\"schema\": 1, \"revision\": int, \"events\": list}."""
        raise NotImplementedError

    def append(self, expected_revision: int, event: dict) -> int:
        """Append ``event`` if revision matches; return record revision or raise ConflictError."""
        raise NotImplementedError
